INSERT INTO public.drug_interactions
  (drug_a_id, drug_b_id, severity, summary_pt, summary_en, mechanism_pt, mechanism_en,
   management_pt, management_en, monitoring_pt, monitoring_en, red_flags_pt, red_flags_en,
   source_pt, source_en, status)
SELECT LEAST(a.id, b.id), GREATEST(a.id, b.id), v.severity, v.summary_pt, v.summary_en,
       v.mechanism_pt, v.mechanism_en, v.management_pt, v.management_en,
       v.monitoring_pt, v.monitoring_en, v.red_flags_pt, v.red_flags_en,
       v.source_pt, v.source_en, 'published'
FROM (VALUES
  ('cetirizina', 'ritonavir', 'moderate', 'Cetirizina + ritonavir: possível aumento da exposição à cetirizina.', 'Cetirizine + ritonavir: possible increased cetirizine exposure.', 'O ritonavir pode aumentar a concentração da cetirizina (interação farmacocinética descrita no rótulo).', 'Ritonavir may raise cetirizine concentrations (pharmacokinetic interaction described in the label).', 'Vigiar sonolência excessiva e efeitos adversos do anti-histamínico.', 'Watch for excessive drowsiness and antihistamine adverse effects.', 'Efeitos sedativos e tolerância à terapêutica.', 'Sedative effects and tolerance to therapy.', 'Sonolência marcada, boca seca, confusão.', 'Marked drowsiness, dry mouth, confusion.', 'DailyMed (FDA) — rótulo aprovado Cetirizina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b92d959d-dd35-b2a3-e053-2995a90af3ff ; rótulo aprovado Ritonavir: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d2f8c6ba-5e06-4b03-8ca5-b4fd7e5a8925 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Cetirizine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b92d959d-dd35-b2a3-e053-2995a90af3ff ; approved Ritonavir label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d2f8c6ba-5e06-4b03-8ca5-b4fd7e5a8925 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('loratadina', 'eritromicina', 'moderate', 'Loratadina + eritromicina: possível aumento das concentrações de loratadina.', 'Loratadine + erythromycin: possible increased loratadine concentrations.', 'A eritromicina (inibidor do CYP3A4) reduz o metabolismo da loratadina.', 'Erythromycin (CYP3A4 inhibitor) reduces loratadine metabolism.', 'Vigiar sedação e efeitos adversos; a maioria tolera sem ajuste de dose.', 'Watch for sedation and adverse effects; most tolerate without dose adjustment.', 'Sintomas de excesso de anti-histamínico.', 'Symptoms of antihistamine excess.', 'Sonolência, cefaleias, palpitações.', 'Drowsiness, headache, palpitations.', 'DailyMed (FDA) — rótulo aprovado Loratadina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=569a35be-d653-181c-e063-6294a90a6eb9 ; rótulo aprovado Eritromicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0c05e1f7-a3d4-8e69-e063-6394a90aecc3 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Loratadine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=569a35be-d653-181c-e063-6294a90a6eb9 ; approved Erythromycin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0c05e1f7-a3d4-8e69-e063-6394a90aecc3 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('loratadina', 'cetoconazol', 'moderate', 'Loratadina + cetoconazol: possível aumento das concentrações de loratadina.', 'Loratadine + ketoconazole: possible increased loratadine concentrations.', 'O cetoconazol (inibidor do CYP3A4 e da P-gp) reduz a depuração da loratadina.', 'Ketoconazole (CYP3A4 and P-gp inhibitor) reduces loratadine clearance.', 'Vigiar sonolência; em ensaios não se observou prolongamento do QTc relevante.', 'Watch for drowsiness; trials showed no relevant QTc prolongation.', 'Efeitos sedativos e eletrocardiograma se fatores de risco.', 'Sedative effects and ECG if risk factors present.', 'Síncope, palpitações, sonolência acentuada.', 'Syncope, palpitations, marked drowsiness.', 'DailyMed (FDA) — rótulo aprovado Loratadina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=569a35be-d653-181c-e063-6294a90a6eb9 ; rótulo aprovado Cetoconazol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f162e616-21b4-49b1-b437-15e21001a6f0 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Loratadine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=569a35be-d653-181c-e063-6294a90a6eb9 ; approved Ketoconazole label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f162e616-21b4-49b1-b437-15e21001a6f0 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('desloratadina', 'eritromicina', 'moderate', 'Desloratadina + eritromicina: possível aumento das concentrações de desloratadina.', 'Desloratadine + erythromycin: possible increased desloratadine concentrations.', 'A eritromicina reduz o metabolismo da desloratadina (CYP3A4).', 'Erythromycin reduces desloratadine metabolism (CYP3A4).', 'Vigiar sedação; não é geralmente necessário ajuste de dose.', 'Watch for sedation; dose adjustment is usually not required.', 'Efeitos adversos do anti-histamínico.', 'Antihistamine adverse effects.', 'Sonolência, xerostomia, cefaleia.', 'Drowsiness, dry mouth, headache.', 'DailyMed (FDA) — rótulo aprovado Desloratadina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2a90b899-7746-43dc-ac8a-e754428eb30c ; rótulo aprovado Eritromicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0c05e1f7-a3d4-8e69-e063-6394a90aecc3 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Desloratadine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2a90b899-7746-43dc-ac8a-e754428eb30c ; approved Erythromycin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0c05e1f7-a3d4-8e69-e063-6394a90aecc3 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('desloratadina', 'cetoconazol', 'moderate', 'Desloratadina + cetoconazol: possível aumento das concentrações de desloratadina.', 'Desloratadine + ketoconazole: possible increased desloratadine concentrations.', 'O cetoconazol inibe o CYP3A4, elevando os níveis de desloratadina.', 'Ketoconazole inhibits CYP3A4, raising desloratadine levels.', 'Vigiar sedação e efeitos adversos.', 'Watch for sedation and adverse effects.', 'Sintomas de excesso de anti-histamínico.', 'Symptoms of antihistamine excess.', 'Sonolência, palpitações, tonturas.', 'Drowsiness, palpitations, dizziness.', 'DailyMed (FDA) — rótulo aprovado Desloratadina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2a90b899-7746-43dc-ac8a-e754428eb30c ; rótulo aprovado Cetoconazol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f162e616-21b4-49b1-b437-15e21001a6f0 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Desloratadine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2a90b899-7746-43dc-ac8a-e754428eb30c ; approved Ketoconazole label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f162e616-21b4-49b1-b437-15e21001a6f0 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('fexofenadina', 'eritromicina', 'moderate', 'Fexofenadina + eritromicina: aumento da exposição à fexofenadina (transporte OATP/P-gp).', 'Fexofenadine + erythromycin: increased fexofenadine exposure (OATP/P-gp transport).', 'A eritromicina interfere com o transporte intestinal (P-gp/OATP), elevando os níveis de fexofenadina.', 'Erythromycin interferes with intestinal transport (P-gp/OATP), raising fexofenadine levels.', 'Vigiar efeitos adversos; sem relevância clínica significativa para a maioria.', 'Watch for adverse effects; not clinically significant for most.', 'Efeitos adversos do anti-histamínico.', 'Antihistamine adverse effects.', 'Náuseas, tonturas, sonolência.', 'Nausea, dizziness, drowsiness.', 'DailyMed (FDA) — rótulo aprovado Fexofenadina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=dd0da52b-fc82-4ec9-854c-0d7c52e926fb ; rótulo aprovado Eritromicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0c05e1f7-a3d4-8e69-e063-6394a90aecc3 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Fexofenadine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=dd0da52b-fc82-4ec9-854c-0d7c52e926fb ; approved Erythromycin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0c05e1f7-a3d4-8e69-e063-6394a90aecc3 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('fexofenadina', 'cetoconazol', 'moderate', 'Fexofenadina + cetoconazol: aumento da exposição à fexofenadina.', 'Fexofenadine + ketoconazole: increased fexofenadine exposure.', 'O cetoconazol interfere com o transporte intestinal da fexofenadina (P-gp/OATP).', 'Ketoconazole interferes with intestinal fexofenadine transport (P-gp/OATP).', 'Vigiar efeitos adversos; sem impacto clínico relevante na maioria dos doentes.', 'Watch for adverse effects; no relevant clinical impact for most patients.', 'Efeitos adversos do anti-histamínico.', 'Antihistamine adverse effects.', 'Sonolência, tonturas, náuseas.', 'Drowsiness, dizziness, nausea.', 'DailyMed (FDA) — rótulo aprovado Fexofenadina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=dd0da52b-fc82-4ec9-854c-0d7c52e926fb ; rótulo aprovado Cetoconazol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f162e616-21b4-49b1-b437-15e21001a6f0 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Fexofenadine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=dd0da52b-fc82-4ec9-854c-0d7c52e926fb ; approved Ketoconazole label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f162e616-21b4-49b1-b437-15e21001a6f0 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('levocetirizina', 'ritonavir', 'moderate', 'Levocetirizina + ritonavir: possível aumento da exposição à levocetirizina.', 'Levocetirizine + ritonavir: possible increased levocetirizine exposure.', 'O ritonavir pode reduzir a depuração da levocetirizina.', 'Ritonavir may reduce levocetirizine clearance.', 'Vigiar sedação e efeitos adversos.', 'Watch for sedation and adverse effects.', 'Efeitos sedativos e tolerância.', 'Sedative effects and tolerance.', 'Sonolência, fadiga, boca seca.', 'Drowsiness, fatigue, dry mouth.', 'DailyMed (FDA) — rótulo aprovado Levocetirizina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f722b84-08de-7e6a-41ac-2c9d9bb9fb43 ; rótulo aprovado Ritonavir: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d2f8c6ba-5e06-4b03-8ca5-b4fd7e5a8925 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Levocetirizine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1f722b84-08de-7e6a-41ac-2c9d9bb9fb43 ; approved Ritonavir label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d2f8c6ba-5e06-4b03-8ca5-b4fd7e5a8925 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('difenidramina', 'morfina', 'moderate', 'Anti-histamínico sedativo + opioide: depressão do SNC aditiva.', 'Sedating antihistamine + opioid: additive CNS depression.', 'Ambos deprimem o sistema nervoso central, potenciando a sedação e a depressão respiratória.', 'Both depress the CNS, potentiating sedation and respiratory depression.', 'Evitar a associação; se inevitável, usar a menor dose e vigiar sedação/respiração.', 'Avoid the combination; if unavoidable, use the lowest dose and watch sedation/respiration.', 'Nível de consciência, frequência respiratória, oximetria.', 'Level of consciousness, respiratory rate, oximetry.', 'Sonolência profunda, bradipneia, confusão.', 'Deep drowsiness, bradypnoea, confusion.', 'DailyMed (FDA) — rótulo aprovado Difenidramina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d8944f3c-acef-4ebe-9633-7d641ae95edf ; rótulo aprovado Morfina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=57ee014e-744e-65e1-e063-6394a90a8c93 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Diphenhydramine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d8944f3c-acef-4ebe-9633-7d641ae95edf ; approved Morphine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=57ee014e-744e-65e1-e063-6394a90a8c93 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('difenidramina', 'tramadol', 'moderate', 'Anti-histamínico sedativo + tramadol: sedação aditiva e risco de convulsões.', 'Sedating antihistamine + tramadol: additive sedation and seizure risk.', 'Efeito depressor do SNC aditivo; o tramadol baixa o limiar convulsivo.', 'Additive CNS depressant effect; tramadol lowers the seizure threshold.', 'Evitar em doentes idosos/frágeis; vigiar sedação e sintomas neurológicos.', 'Avoid in elderly/frail patients; watch for sedation and neurological symptoms.', 'Nível de consciência e sintomas neurológicos.', 'Level of consciousness and neurological symptoms.', 'Convulsões, sonolência excessiva, confusão.', 'Seizures, excessive drowsiness, confusion.', 'DailyMed (FDA) — rótulo aprovado Difenidramina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d8944f3c-acef-4ebe-9633-7d641ae95edf ; rótulo aprovado Tramadol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9f0e33bd-65f8-446a-886f-e7e16a142ce5 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Diphenhydramine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d8944f3c-acef-4ebe-9633-7d641ae95edf ; approved Tramadol label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=9f0e33bd-65f8-446a-886f-e7e16a142ce5 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('difenidramina', 'sertralina', 'minor', 'Anti-histamínico sedativo + ISRS: sedação aditiva ligeira.', 'Sedating antihistamine + SSRI: mild additive sedation.', 'Ambos podem causar sedação e efeitos anticolinérgicos aditivos.', 'Both may cause sedation and additive anticholinergic effects.', 'Usar com precaução; vigiar sonolência diurna.', 'Use with caution; watch for daytime drowsiness.', 'Sintomas de sedação excessiva.', 'Symptoms of excessive sedation.', 'Sonolência diurna, confusão em idosos.', 'Daytime drowsiness, confusion in the elderly.', 'DailyMed (FDA) — rótulo aprovado Difenidramina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d8944f3c-acef-4ebe-9633-7d641ae95edf ; rótulo aprovado Sertralina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=91e24d17-ff0a-449c-9472-b9df74c98456 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Diphenhydramine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d8944f3c-acef-4ebe-9633-7d641ae95edf ; approved Sertraline label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=91e24d17-ff0a-449c-9472-b9df74c98456 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('dexametasona', 'warfarina', 'moderate', 'Corticosteroide + anticoagulante: alteração do INR e risco hemorrágico.', 'Corticosteroid + anticoagulant: altered INR and bleeding risk.', 'Os corticosteroides podem potenciar ou reduzir o efeito da varfarina (efeito variável sobre a hemostase e a mucosa GI).', 'Corticosteroids may potentiate or reduce warfarin effect (variable effect on haemostasis and GI mucosa).', 'Monitorizar INR após início/ajuste de corticosteroide; considerar gastroprotecção.', 'Monitor INR after starting/adjusting corticosteroids; consider gastroprotection.', 'INR periódico e sintomas digestivos.', 'Periodic INR and GI symptoms.', 'Melena, hematemese, hemorragia.', 'Melena, haematemesis, bleeding.', 'DailyMed (FDA) — rótulo aprovado Dexametasona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; rótulo aprovado Varfarina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Dexamethasone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; approved Warfarin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=541c9a70-adaf-4ef3-94ba-ad4e70dfa057 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('dexametasona', 'furosemida', 'moderate', 'Corticosteroide + diurético de ansa: risco de hipocaliemia aditiva.', 'Corticosteroid + loop diuretic: additive hypokalaemia risk.', 'Ambos aumentam a perda renal de potássio.', 'Both increase renal potassium loss.', 'Monitorizar o potássio sérico; considerar suplementação se necessário.', 'Monitor serum potassium; consider supplementation if needed.', 'Potássio sérico e sintomas de hipocaliemia.', 'Serum potassium and hypokalaemia symptoms.', 'Fraqueza, cãibras, arritmias.', 'Weakness, cramps, arrhythmias.', 'DailyMed (FDA) — rótulo aprovado Dexametasona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; rótulo aprovado Furosemida: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6d9caaab-d874-4cf1-b9fe-408452a18998 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Dexamethasone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; approved Furosemide label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=6d9caaab-d874-4cf1-b9fe-408452a18998 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('dexametasona', 'hidroclorotiazida', 'moderate', 'Corticosteroide + tiazida: hipocaliemia e hiperglicemia aditivas.', 'Corticosteroid + thiazide: additive hypokalaemia and hyperglycaemia.', 'Ambos favorecem a perda de potássio e a elevação da glicemia.', 'Both promote potassium loss and raised blood glucose.', 'Monitorizar potássio e glicemia; ajustar terapêutica se necessário.', 'Monitor potassium and blood glucose; adjust therapy if needed.', 'Potássio, glicemia e tensão arterial.', 'Potassium, blood glucose and blood pressure.', 'Fraqueza, cãibras, poliúria, descompensação glicémica.', 'Weakness, cramps, polyuria, glycaemic decompensation.', 'DailyMed (FDA) — rótulo aprovado Dexametasona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; rótulo aprovado Hidroclorotiazida: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0789baef-3424-43ab-a3fb-4908172da565 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Dexamethasone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; approved Hydrochlorothiazide label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0789baef-3424-43ab-a3fb-4908172da565 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('dexametasona', 'digoxina', 'moderate', 'Corticosteroide + digoxina: a hipocaliemia induzida aumenta a toxicidade digitálica.', 'Corticosteroid + digoxin: induced hypokalaemia increases digoxin toxicity.', 'A perda de potássio associada ao corticosteroide sensibiliza o miocárdio à digoxina.', 'Corticosteroid-associated potassium loss sensitises the myocardium to digoxin.', 'Monitorizar potássio e sinais de toxicidade digitálica.', 'Monitor potassium and signs of digoxin toxicity.', 'Potássio sérico e eletrocardiograma.', 'Serum potassium and ECG.', 'Náuseas, arritmias, confusão, visão a cores alterada.', 'Nausea, arrhythmias, confusion, altered colour vision.', 'DailyMed (FDA) — rótulo aprovado Dexametasona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; rótulo aprovado Digoxina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e61d2108-d871-44c0-b12a-2e61fbb56967 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Dexamethasone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; approved Digoxin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e61d2108-d871-44c0-b12a-2e61fbb56967 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('dexametasona', 'carbamazepina', 'moderate', 'Corticosteroide + carbamazepina: indução do CYP3A4 reduz o efeito do corticosteroide.', 'Corticosteroid + carbamazepine: CYP3A4 induction reduces corticosteroid effect.', 'A carbamazepina (inductor do CYP3A4) acelera o metabolismo da dexametasona.', 'Carbamazepine (CYP3A4 inducer) accelerates dexamethasone metabolism.', 'Vigiar resposta clínica; pode ser necessário aumentar a dose do corticosteroide.', 'Watch clinical response; a higher corticosteroid dose may be needed.', 'Resposta clínica à terapêutica.', 'Clinical response to therapy.', 'Falta de controlo dos sintomas inflamatórios/alérgicos.', 'Lack of control of inflammatory/allergic symptoms.', 'DailyMed (FDA) — rótulo aprovado Dexametasona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; rótulo aprovado Carbamazepina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=97e6e175-75e8-437b-b457-ddb1ae4e857d — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Dexamethasone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; approved Carbamazepine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=97e6e175-75e8-437b-b457-ddb1ae4e857d — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('dexametasona', 'fenitoina', 'moderate', 'Corticosteroide + fenitoína: indução enzimática reduz o efeito de ambos.', 'Corticosteroid + phenytoin: enzyme induction reduces the effect of both.', 'A fenitoína induz o CYP3A4 (metabolismo da dexametasona) e a dexametasona altera o metabolismo da fenitoína.', 'Phenytoin induces CYP3A4 (dexamethasone metabolism) and dexamethasone alters phenytoin metabolism.', 'Monitorizar resposta e, se possível, dos níveis de fenitoína.', 'Monitor response and, if feasible, phenytoin levels.', 'Resposta clínica e níveis séricos de fenitoína.', 'Clinical response and serum phenytoin levels.', 'Crises convulsivas, falta de controlo alérgico/inflamatório.', 'Seizures, lack of allergic/inflammatory control.', 'DailyMed (FDA) — rótulo aprovado Dexametasona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; rótulo aprovado Fenitoína: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ef4e97a7-cd18-47a9-a016-2eca5481a87e — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Dexamethasone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; approved Phenytoin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ef4e97a7-cd18-47a9-a016-2eca5481a87e — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('dexametasona', 'claritromicina', 'moderate', 'Corticosteroide + claritromicina: a inibição do CYP3A4 aumenta a exposição ao corticosteroide.', 'Corticosteroid + clarithromycin: CYP3A4 inhibition increases corticosteroid exposure.', 'A claritromicina inibe o CYP3A4, reduzindo o metabolismo da dexametasona.', 'Clarithromycin inhibits CYP3A4, reducing dexamethasone metabolism.', 'Vigiar efeitos dos corticosteroides (hiperglicemia, retenção de líquidos, síndrome de Cushing).', 'Watch for corticosteroid effects (hyperglycaemia, fluid retention, Cushing syndrome).', 'Glicemia, tensão arterial e sinais de excesso de corticosteroides.', 'Blood glucose, blood pressure and signs of corticosteroid excess.', 'Ganho de peso, edema, hiperglicemia.', 'Weight gain, oedema, hyperglycaemia.', 'DailyMed (FDA) — rótulo aprovado Dexametasona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; rótulo aprovado Claritromicina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d836ae7e-fdbf-4dcb-a90d-ede1dcbc3e67 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Dexamethasone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; approved Clarithromycin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d836ae7e-fdbf-4dcb-a90d-ede1dcbc3e67 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('dexametasona', 'ritonavir', 'moderate', 'Corticosteroide + ritonavir: inibição do CYP3A4 aumenta muito a exposição ao corticosteroide.', 'Corticosteroid + ritonavir: CYP3A4 inhibition markedly increases corticosteroid exposure.', 'O ritonavir (inibidor potente do CYP3A4) reduz o metabolismo da dexametasona, com risco de síndrome de Cushing.', 'Ritonavir (potent CYP3A4 inhibitor) reduces dexamethasone metabolism, risking Cushing syndrome.', 'Evitar a associação; se inevitável, reduzir a dose de dexametasona e vigiar.', 'Avoid the combination; if unavoidable, reduce dexamethasone dose and monitor.', 'Glicemia, tensão arterial, sinais de excesso de corticosteroides.', 'Blood glucose, blood pressure, signs of corticosteroid excess.', 'Síndrome de Cushing, hiperglicemia, edema.', 'Cushing syndrome, hyperglycaemia, oedema.', 'DailyMed (FDA) — rótulo aprovado Dexametasona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; rótulo aprovado Ritonavir: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d2f8c6ba-5e06-4b03-8ca5-b4fd7e5a8925 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Dexamethasone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; approved Ritonavir label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=d2f8c6ba-5e06-4b03-8ca5-b4fd7e5a8925 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('dexametasona', 'aspirina', 'moderate', 'Corticosteroide + aspirina: risco gastrointestinal aditivo (úlcera/hemorragia).', 'Corticosteroid + aspirin: additive gastrointestinal risk (ulcer/bleeding).', 'Ambos enfraquecem a proteção da mucosa gástrica.', 'Both weaken gastric mucosal protection.', 'Considerar gastroprotecção (IBP) em doentes de risco.', 'Consider gastroprotection (PPI) in at-risk patients.', 'Sintomas digestivos e sinais de hemorragia.', 'GI symptoms and signs of bleeding.', 'Melena, hematemese, dor abdominal.', 'Melena, haematemesis, abdominal pain.', 'DailyMed (FDA) — rótulo aprovado Dexametasona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; rótulo aprovado Ácido acetilsalicílico: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3ba0a9f2-062a-401e-82eb-54383a822366 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Dexamethasone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; approved Aspirin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3ba0a9f2-062a-401e-82eb-54383a822366 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('dexametasona', 'ibuprofeno', 'moderate', 'Corticosteroide + AINE: risco gastrointestinal (úlcera/hemorragia) aditivo.', 'Corticosteroid + NSAID: additive gastrointestinal risk (ulcer/bleeding).', 'Ambos enfraquecem a proteção da mucosa gástrica.', 'Both weaken gastric mucosal protection.', 'Evitar a associação quando possível; se necessária, usar gastroprotecção.', 'Avoid the combination when possible; if needed, use gastroprotection.', 'Sintomas digestivos e hemograma se hemorragia.', 'GI symptoms and full blood count if bleeding.', 'Dor epigástrica, melena, hematemese.', 'Epigastric pain, melena, haematemesis.', 'DailyMed (FDA) — rótulo aprovado Dexametasona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; rótulo aprovado Ibuprofeno: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=291602fa-8ebe-4200-bba7-9798c90f8a50 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Dexamethasone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7cbd9005-7df2-47ee-adb3-7244c1c69bc3 ; approved Ibuprofen label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=291602fa-8ebe-4200-bba7-9798c90f8a50 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('adrenalina', 'amiodarona', 'moderate', 'Adrenalina + antiarrítmico: risco de arritmias ventriculares.', 'Epinephrine + antiarrhythmic: risk of ventricular arrhythmias.', 'A estimulação adrenérgica adiciona-se a fármacos que prolongam a repolarização, aumentando o risco de arritmia.', 'Adrenergic stimulation adds to drugs that prolong repolarisation, increasing arrhythmia risk.', 'Usar com precaução em doentes com doença cardíaca; monitorizar ritmo cardíaco.', 'Use with caution in cardiac patients; monitor heart rhythm.', 'Eletrocardiograma e tensão arterial.', 'ECG and blood pressure.', 'Palpitações, taquicardia, arritmias ventriculares.', 'Palpitations, tachycardia, ventricular arrhythmias.', 'DailyMed (FDA) — rótulo aprovado Adrenalina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5726eeca-db88-ba8e-e063-6294a90a927d ; rótulo aprovado Amiodarona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=51a88e8e-da02-4b97-9e7e-442fbffd908d — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Epinephrine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5726eeca-db88-ba8e-e063-6294a90a927d ; approved Amiodarone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=51a88e8e-da02-4b97-9e7e-442fbffd908d — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('adrenalina', 'digoxina', 'moderate', 'Adrenalina + digoxina: risco de arritmias (sensibilização miocárdica).', 'Epinephrine + digoxin: risk of arrhythmias (myocardial sensitisation).', 'Ambos aumentam a automaticidade miocárdica; a hipocaliemia potenciada aumenta o risco de arritmias.', 'Both increase myocardial automaticity; potentiated hypokalaemia increases arrhythmia risk.', 'Monitorizar ritmo cardíaco e potássio em doentes com doença cardíaca.', 'Monitor heart rhythm and potassium in cardiac patients.', 'Eletrocardiograma e potássio sérico.', 'ECG and serum potassium.', 'Arritmias, palpitações, hipocaliemia.', 'Arrhythmias, palpitations, hypokalaemia.', 'DailyMed (FDA) — rótulo aprovado Adrenalina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5726eeca-db88-ba8e-e063-6294a90a927d ; rótulo aprovado Digoxina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e61d2108-d871-44c0-b12a-2e61fbb56967 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Epinephrine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5726eeca-db88-ba8e-e063-6294a90a927d ; approved Digoxin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=e61d2108-d871-44c0-b12a-2e61fbb56967 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('adrenalina', 'teofilina', 'moderate', 'Adrenalina + teofilina: efeitos cardíacos e hipocaliemia aditivos.', 'Epinephrine + theophylline: additive cardiac effects and hypokalaemia.', 'Ambos são estimulantes β-adrenérgicos; aumentam o risco de taquicardia, tremores e hipocaliemia.', 'Both are β-adrenergic stimulants; they increase the risk of tachycardia, tremor and hypokalaemia.', 'Monitorizar potássio e ritmo cardíaco, sobretudo em doentes cardiovasculares.', 'Monitor potassium and heart rhythm, especially in cardiovascular patients.', 'Potássio sérico e eletrocardiograma.', 'Serum potassium and ECG.', 'Taquiarritmias, tremores, hipocaliemia sintomática.', 'Tachyarrhythmias, tremor, symptomatic hypokalaemia.', 'DailyMed (FDA) — rótulo aprovado Adrenalina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5726eeca-db88-ba8e-e063-6294a90a927d ; rótulo aprovado Teofilina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e64036a-ee3e-42e7-9e59-881f88a4e298 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Epinephrine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5726eeca-db88-ba8e-e063-6294a90a927d ; approved Theophylline label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e64036a-ee3e-42e7-9e59-881f88a4e298 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('adrenalina', 'salbutamol', 'moderate', 'Adrenalina + β2-agonista: efeitos simpáticos e hipocaliemia aditivos.', 'Epinephrine + β2-agonist: additive sympathetic effects and hypokalaemia.', 'A sobreposição β-adrenérgica aumenta taquicardia, tremores e perda de potássio.', 'Overlapping β-adrenergic effects increase tachycardia, tremor and potassium loss.', 'Monitorizar potássio e sintomas cardiovasculares em doentes de risco.', 'Monitor potassium and cardiovascular symptoms in at-risk patients.', 'Potássio e ritmo cardíaco.', 'Potassium and heart rhythm.', 'Palpitações, tremores, hipocaliemia.', 'Palpitations, tremor, hypokalaemia.', 'DailyMed (FDA) — rótulo aprovado Adrenalina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5726eeca-db88-ba8e-e063-6294a90a927d ; rótulo aprovado Salbutamol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3236f82c-14e9-dfd4-e063-6294a90ac43d — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Epinephrine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5726eeca-db88-ba8e-e063-6294a90a927d ; approved Salbutamol label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3236f82c-14e9-dfd4-e063-6294a90ac43d — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('adrenalina', 'ciprofloxacina', 'minor', 'Adrenalina + fluoroquinolona: risco teórico de prolongamento do QTc.', 'Epinephrine + fluoroquinolone: theoretical risk of QTc prolongation.', 'Ambos podem prolongar o intervalo QTc em doentes suscetíveis.', 'Both may prolong the QTc interval in susceptible patients.', 'Usar com precaução em doentes com fatores de risco de QTc prolongado.', 'Use with caution in patients with QTc risk factors.', 'Eletrocardiograma em doentes de risco.', 'ECG in at-risk patients.', 'Palpitações, síncope.', 'Palpitations, syncope.', 'DailyMed (FDA) — rótulo aprovado Adrenalina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5726eeca-db88-ba8e-e063-6294a90a927d ; rótulo aprovado Ciprofloxacina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c527d138-e32c-418f-9573-a3d8a796279f — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Epinephrine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5726eeca-db88-ba8e-e063-6294a90a927d ; approved Ciprofloxacin label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=c527d138-e32c-418f-9573-a3d8a796279f — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('pseudoefedrina', 'amiodarona', 'moderate', 'Descongestionante simpaticomimético + antiarrítmico: risco de arritmias e efeito pressor.', 'Sympathomimetic decongestant + antiarrhythmic: risk of arrhythmias and pressor effect.', 'A pseudoefedrina (α-agonista) aumenta a tensão arterial e o trabalho cardíaco, com risco de arritmia em doentes predispostos.', 'Pseudoephedrine (α-agonist) raises blood pressure and cardiac work, risking arrhythmia in predisposed patients.', 'Evitar em doença cardiovascular; se usado, monitorizar TA e ritmo.', 'Avoid in cardiovascular disease; if used, monitor BP and rhythm.', 'Tensão arterial e eletrocardiograma.', 'Blood pressure and ECG.', 'Hipertensão, taquicardia, arritmias.', 'Hypertension, tachycardia, arrhythmias.', 'DailyMed (FDA) — rótulo aprovado Pseudoefedrina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=78faa497-6743-b85b-e053-2a91aa0ae822 ; rótulo aprovado Amiodarona: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=51a88e8e-da02-4b97-9e7e-442fbffd908d — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Pseudoephedrine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=78faa497-6743-b85b-e053-2a91aa0ae822 ; approved Amiodarone label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=51a88e8e-da02-4b97-9e7e-442fbffd908d — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('pseudoefedrina', 'teofilina', 'moderate', 'Descongestionante + teofilina: estimulação aditiva e hipocaliemia.', 'Decongestant + theophylline: additive stimulation and hypokalaemia.', 'Efeitos estimulantes aditivos (taquicardia, tremores) e possível perda de potássio.', 'Additive stimulant effects (tachycardia, tremor) and possible potassium loss.', 'Vigiar sintomas cardiovasculares; monitorizar potássio em doentes de risco.', 'Watch for cardiovascular symptoms; monitor potassium in at-risk patients.', 'Potássio e sintomas adrenérgicos.', 'Potassium and adrenergic symptoms.', 'Palpitações, tremores, insónia.', 'Palpitations, tremor, insomnia.', 'DailyMed (FDA) — rótulo aprovado Pseudoefedrina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=78faa497-6743-b85b-e053-2a91aa0ae822 ; rótulo aprovado Teofilina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e64036a-ee3e-42e7-9e59-881f88a4e298 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Pseudoephedrine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=78faa497-6743-b85b-e053-2a91aa0ae822 ; approved Theophylline label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5e64036a-ee3e-42e7-9e59-881f88a4e298 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('pseudoefedrina', 'salbutamol', 'moderate', 'Descongestionante + β2-agonista: efeitos simpáticos aditivos.', 'Decongestant + β2-agonist: additive sympathetic effects.', 'A sobreposição α/β-adrenérgica aumenta a tensão arterial e a taquicardia.', 'Overlapping α/β-adrenergic effects raise blood pressure and heart rate.', 'Usar com precaução em doentes cardiovasculares; vigiar sintomas.', 'Use with caution in cardiovascular patients; watch for symptoms.', 'Tensão arterial e ritmo cardíaco.', 'Blood pressure and heart rhythm.', 'Hipertensão, palpitações, tremores.', 'Hypertension, palpitations, tremor.', 'DailyMed (FDA) — rótulo aprovado Pseudoefedrina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=78faa497-6743-b85b-e053-2a91aa0ae822 ; rótulo aprovado Salbutamol: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3236f82c-14e9-dfd4-e063-6294a90ac43d — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Pseudoephedrine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=78faa497-6743-b85b-e053-2a91aa0ae822 ; approved Salbutamol label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3236f82c-14e9-dfd4-e063-6294a90ac43d — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('pseudoefedrina', 'sertralina', 'minor', 'Descongestionante + ISRS: possível aumento do efeito pressor e serotonérgico.', 'Decongestant + SSRI: possible increased pressor and serotonergic effect.', 'A pseudoefedrina pode adicionar efeito pressor; o ISRS interfere com o metabolismo.', 'Pseudoephedrine may add a pressor effect; the SSRI interferes with metabolism.', 'Vigiar tensão arterial e sintomas serotonérgicos.', 'Monitor blood pressure and serotonergic symptoms.', 'Tensão arterial em doentes de risco.', 'Blood pressure in at-risk patients.', 'Hipertensão, agitação, tremores.', 'Hypertension, agitation, tremor.', 'DailyMed (FDA) — rótulo aprovado Pseudoefedrina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=78faa497-6743-b85b-e053-2a91aa0ae822 ; rótulo aprovado Sertralina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=91e24d17-ff0a-449c-9472-b9df74c98456 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Pseudoephedrine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=78faa497-6743-b85b-e053-2a91aa0ae822 ; approved Sertraline label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=91e24d17-ff0a-449c-9472-b9df74c98456 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)'),
  ('pseudoefedrina', 'fluoxetina', 'minor', 'Descongestionante + ISRS: possível aumento do efeito pressor.', 'Decongestant + SSRI: possible increased pressor effect.', 'Efeito simpaticomimético aditivo em doentes a ISRS (risco de hipertensão/taquicardia).', 'Additive sympathomimetic effect in patients on SSRIs (risk of hypertension/tachycardia).', 'Vigiar tensão arterial e frequência cardíaca.', 'Monitor blood pressure and heart rate.', 'Tensão arterial.', 'Blood pressure.', 'Hipertensão, palpitações.', 'Hypertension, palpitations.', 'DailyMed (FDA) — rótulo aprovado Pseudoefedrina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=78faa497-6743-b85b-e053-2a91aa0ae822 ; rótulo aprovado Fluoxetina: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=09fb3100-1e06-4cdc-8016-7e4f5d097490 — referência adicional: Prontuário Terapêutico do INFARMED (11.ª ed., 2012)', 'DailyMed (FDA) — approved Pseudoephedrine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=78faa497-6743-b85b-e053-2a91aa0ae822 ; approved Fluoxetine label: https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=09fb3100-1e06-4cdc-8016-7e4f5d097490 — additional reference: Prontuário Terapêutico do INFARMED (11th ed., 2012)')
) AS v(slug_a, slug_b, severity, summary_pt, summary_en,
       mechanism_pt, mechanism_en, management_pt, management_en,
       monitoring_pt, monitoring_en, red_flags_pt, red_flags_en,
       source_pt, source_en)
JOIN public.drugs a ON a.slug = v.slug_a
JOIN public.drugs b ON b.slug = v.slug_b
ON CONFLICT (drug_a_id, drug_b_id) DO NOTHING;

