  ('desloratadina', 'alcool', 'Álcool', 'Alcohol', 'minor', 'O álcool pode potenciar a sonolência.', 'Alcohol may potentiate drowsiness.', 'Limitar o consumo de álcool em doentes suscetíveis.', 'Limit alcohol in susceptible patients.', 'EMC-UK (MHRA) — SmPC aprovada Desloratadina: https://www.medicines.org.uk/emc/product/14722/smpc', 'EMC-UK (MHRA) — approved Desloratadine SmPC: https://www.medicines.org.uk/emc/product/14722/smpc', 1),
  ('desloratadina', 'toranja', 'Toranja', 'Grapefruit', 'moderate', 'A toranja (sumo) pode aumentar as concentrações de desloratadina.', 'Grapefruit (juice) may raise desloratadine concentrations.', 'Evitar sumo de toranja durante o tratamento.', 'Avoid grapefruit juice during treatment.', 'EMC-UK (MHRA) — SmPC aprovada Desloratadina: https://www.medicines.org.uk/emc/product/14722/smpc', 'EMC-UK (MHRA) — approved Desloratadine SmPC: https://www.medicines.org.uk/emc/product/14722/smpc', 1),
  ('fexofenadina', 'sumos_frutas', 'Sumo de laranja, maçã e toranja', 'Orange, apple and grapefruit juice', 'moderate', 'Os sumos de laranja, maçã e toranja reduzem a absorção da fexofenadina (inibição do OATP).', 'Orange, apple and grapefruit juice reduce fexofenadine absorption (OATP inhibition).', 'Tomar a fexofenadina com água e separar dos sumos de fruta.', 'Take fexofenadine with water and separate from fruit juices.', 'EMC-UK (MHRA) — SmPC aprovada Fexofenadina: https://www.medicines.org.uk/emc/product/13208/smpc', 'EMC-UK (MHRA) — approved Fexofenadine SmPC: https://www.medicines.org.uk/emc/product/13208/smpc', 1),
  ('fexofenadina', 'alcool', 'Álcool', 'Alcohol', 'minor', 'O álcool pode potenciar a sonolência.', 'Alcohol may potentiate drowsiness.', 'Limitar o consumo de álcool.', 'Limit alcohol intake.', 'EMC-UK (MHRA) — SmPC aprovada Fexofenadina: https://www.medicines.org.uk/emc/product/13208/smpc', 'EMC-UK (MHRA) — approved Fexofenadine SmPC: https://www.medicines.org.uk/emc/product/13208/smpc', 1),
  ('levocetirizina', 'alcool', 'Álcool', 'Alcohol', 'moderate', 'O álcool pode potenciar a sonolência e reduzir o desempenho psicomotor.', 'Alcohol may potentiate drowsiness and impair psychomotor performance.', 'Evitar álcool durante o tratamento, sobretudo ao conduzir.', 'Avoid alcohol during treatment, especially when driving.', 'EMC-UK (MHRA) — SmPC aprovada Levocetirizina: https://www.medicines.org.uk/emc/product/9917/smpc', 'EMC-UK (MHRA) — approved Levocetirizine SmPC: https://www.medicines.org.uk/emc/product/9917/smpc', 1),
  ('difenidramina', 'alcool', 'Álcool', 'Alcohol', 'moderate', 'O álcool potencia marcadamente a sedação da difenidramina.', 'Alcohol markedly potentiates diphenhydramine sedation.', 'Evitar álcool durante o tratamento.', 'Avoid alcohol during treatment.', 'EMC-UK (MHRA) — SmPC aprovada Difenidramina: https://www.medicines.org.uk/emc/product/1476/smpc', 'EMC-UK (MHRA) — approved Diphenhydramine SmPC: https://www.medicines.org.uk/emc/product/1476/smpc', 1),
  ('difenidramina', 'alimentos', 'Alimentos', 'Food', 'minor', 'Os alimentos podem reduzir a irritação gástrica.', 'Food may reduce gastric irritation.', 'Pode tomar com alimentos se houver desconforto gástrico.', 'May take with food if stomach discomfort occurs.', 'EMC-UK (MHRA) — SmPC aprovada Difenidramina: https://www.medicines.org.uk/emc/product/1476/smpc', 'EMC-UK (MHRA) — approved Diphenhydramine SmPC: https://www.medicines.org.uk/emc/product/1476/smpc', 1),
  ('dexametasona', 'toranja', 'Toranja', 'Grapefruit', 'moderate', 'A toranja (sumo) inibe o CYP3A4 e aumenta a exposição à dexametasona.', 'Grapefruit (juice) inhibits CYP3A4 and increases dexamethasone exposure.', 'Evitar sumo de toranja durante o tratamento.', 'Avoid grapefruit juice during treatment.', 'EMC-UK (MHRA) — SmPC aprovada Dexametasona: https://www.medicines.org.uk/emc/product/13196/smpc', 'EMC-UK (MHRA) — approved Dexamethasone SmPC: https://www.medicines.org.uk/emc/product/13196/smpc', 1),
  ('dexametasona', 'alcool', 'Álcool', 'Alcohol', 'minor', 'O álcool pode aumentar o risco gastrointestinal.', 'Alcohol may increase GI risk.', 'Limitar o consumo de álcool durante o tratamento.', 'Limit alcohol during treatment.', 'EMC-UK (MHRA) — SmPC aprovada Dexametasona: https://www.medicines.org.uk/emc/product/13196/smpc', 'EMC-UK (MHRA) — approved Dexamethasone SmPC: https://www.medicines.org.uk/emc/product/13196/smpc', 1),
  ('adrenalina', 'cafe_cha', 'Café e bebidas com cafeína', 'Coffee and caffeinated drinks', 'minor', 'A cafeína pode potenciar os efeitos adrenérgicos da adrenalina (tremores, taquicardia).', 'Caffeine may potentiate the adrenergic effects of epinephrine (tremor, tachycardia).', 'Limitar o consumo de cafeína durante o tratamento.', 'Limit caffeine intake during treatment.', 'EMC-UK (MHRA) — SmPC aprovada Adrenalina: https://www.medicines.org.uk/emc/product/3673/smpc', 'EMC-UK (MHRA) — approved Epinephrine SmPC: https://www.medicines.org.uk/emc/product/3673/smpc', 1),
  ('pseudoefedrina', 'cafe_cha', 'Café e bebidas com cafeína', 'Coffee and caffeinated drinks', 'minor', 'A cafeína pode potenciar os efeitos estimulantes da pseudoefedrina (taquicardia, insónia).', 'Caffeine may potentiate the stimulant effects of pseudoephedrine (tachycardia, insomnia).', 'Limitar o consumo de cafeína, sobretudo à noite.', 'Limit caffeine intake, especially at night.', 'EMC-UK (MHRA) — SmPC aprovada Pseudoefedrina: https://www.medicines.org.uk/emc/product/8292/smpc', 'EMC-UK (MHRA) — approved Pseudoephedrine SmPC: https://www.medicines.org.uk/emc/product/8292/smpc', 1),
  ('pseudoefedrina', 'alcool', 'Álcool', 'Alcohol', 'minor', 'O álcool pode potenciar os efeitos cardiovasculares.', 'Alcohol may potentiate the cardiovascular effects.', 'Limitar o consumo de álcool.', 'Limit alcohol intake.', 'EMC-UK (MHRA) — SmPC aprovada Pseudoefedrina: https://www.medicines.org.uk/emc/product/8292/smpc', 'EMC-UK (MHRA) — approved Pseudoephedrine SmPC: https://www.medicines.org.uk/emc/product/8292/smpc', 1),
  ('budesonida', 'toranja', 'Toranja', 'Grapefruit', 'moderate', 'A toranja (sumo) inibe o CYP3A4 e aumenta a exposição à budesonida.', 'Grapefruit (juice) inhibits CYP3A4 and increases budesonide exposure.', 'Evitar sumo de toranja durante o tratamento.', 'Avoid grapefruit juice during treatment.', 'EMC-UK (MHRA) — SmPC aprovada Budesonida: https://www.medicines.org.uk/emc/product/9715/smpc', 'EMC-UK (MHRA) — approved Budesonide SmPC: https://www.medicines.org.uk/emc/product/9715/smpc', 1),
  ('budesonida', 'alcool', 'Álcool', 'Alcohol', 'minor', 'O álcool pode potenciar o risco gastrointestinal dos corticosteroides.', 'Alcohol may potentiate the GI risk of corticosteroids.', 'Limitar o consumo de álcool.', 'Limit alcohol intake.', 'EMC-UK (MHRA) — SmPC aprovada Budesonida: https://www.medicines.org.uk/emc/product/9715/smpc', 'EMC-UK (MHRA) — approved Budesonide SmPC: https://www.medicines.org.uk/emc/product/9715/smpc', 1),
  ('midodrina', 'cafe_cha', 'Café e bebidas com cafeína', 'Coffee and caffeinated drinks', 'minor', 'A cafeína pode potenciar o efeito pressor da midodrina.', 'Caffeine may potentiate the pressor effect of midodrine.', 'Limitar o consumo de cafeína.', 'Limit caffeine intake.', 'EMC-UK (MHRA) — SmPC aprovada Midodrina: https://www.medicines.org.uk/emc/product/12040/smpc', 'EMC-UK (MHRA) — approved Midodrine SmPC: https://www.medicines.org.uk/emc/product/12040/smpc', 1)
