-- 4. Doença / Condição (drug_disease_interactions)
-- ----------------------------------------------------------------
INSERT INTO public.drug_disease_interactions
  (drug_id, condition_slug, condition_pt, condition_en, interaction_type, severity,
   reason_pt, reason_en, advice_pt, advice_en,
   source_pt, source_en, sort_order, status)
SELECT d.id, v.condition_slug, v.condition_pt, v.condition_en, v.interaction_type, v.severity,
       v.reason_pt, v.reason_en, v.advice_pt, v.advice_en,
       v.source_pt, v.source_en, v.sort_order, 'published'
FROM public.drugs d
JOIN (VALUES
  ('cetirizina', 'insuficiencia_renal_grave', 'Insuficiência renal grave', 'Severe renal impairment', 'precaution', 'moderate', 'A cetirizina é excretada por via renal; na insuficiência grave a dose deve ser reduzida.', 'Cetirizine is renally excreted; in severe impairment the dose must be reduced.', 'Reduzir a dose (ex.: 5 mg/dia) em insuficiência renal grave.', 'Reduce the dose (e.g. 5 mg/day) in severe renal impairment.', 'EMC-UK (MHRA) — SmPC aprovada Cetirizina: https://www.medicines.org.uk/emc/product/3217/smpc', 'EMC-UK (MHRA) — approved Cetirizine SmPC: https://www.medicines.org.uk/emc/product/3217/smpc', 1),
  ('loratadina', 'insuficiencia_hepatica_grave', 'Insuficiência hepática grave', 'Severe hepatic impairment', 'precaution', 'moderate', 'O metabolismo hepático reduzido pode aumentar a exposição à loratadina.', 'Reduced hepatic metabolism may increase loratadine exposure.', 'Usar com precaução; dose inicial alternativa em insuficiência hepática grave.', 'Use with caution; alternative initial dose in severe hepatic impairment.', 'EMC-UK (MHRA) — SmPC aprovada Loratadina: https://www.medicines.org.uk/emc/product/10942/smpc', 'EMC-UK (MHRA) — approved Loratadine SmPC: https://www.medicines.org.uk/emc/product/10942/smpc', 1),
  ('desloratadina', 'insuficiencia_renal_grave', 'Insuficiência renal grave', 'Severe renal impairment', 'precaution', 'moderate', 'A desloratadina é eliminada por via renal.', 'Desloratadine is eliminated renally.', 'Usar com precaução e ajustar a dose em insuficiência renal grave.', 'Use with caution and adjust the dose in severe renal impairment.', 'EMC-UK (MHRA) — SmPC aprovada Desloratadina: https://www.medicines.org.uk/emc/product/14722/smpc', 'EMC-UK (MHRA) — approved Desloratadine SmPC: https://www.medicines.org.uk/emc/product/14722/smpc', 1),
  ('desloratadina', 'insuficiencia_hepatica_grave', 'Insuficiência hepática grave', 'Severe hepatic impairment', 'precaution', 'moderate', 'A eliminação reduzida pode aumentar a exposição.', 'Reduced elimination may increase exposure.', 'Usar com precaução.', 'Use with caution.', 'EMC-UK (MHRA) — SmPC aprovada Desloratadina: https://www.medicines.org.uk/emc/product/14722/smpc', 'EMC-UK (MHRA) — approved Desloratadine SmPC: https://www.medicines.org.uk/emc/product/14722/smpc', 1),
  ('fexofenadina', 'insuficiencia_renal_grave', 'Insuficiência renal grave', 'Severe renal impairment', 'precaution', 'moderate', 'A fexofenadina é eliminada por via renal.', 'Fexofenadine is renally eliminated.', 'Dose inicial recomendada de 60 mg uma vez por dia em insuficiência renal grave.', 'Recommended starting dose of 60 mg once daily in severe renal impairment.', 'EMC-UK (MHRA) — SmPC aprovada Fexofenadina: https://www.medicines.org.uk/emc/product/13208/smpc', 'EMC-UK (MHRA) — approved Fexofenadine SmPC: https://www.medicines.org.uk/emc/product/13208/smpc', 1),
  ('levocetirizina', 'insuficiencia_renal_grave', 'Insuficiência renal grave', 'Severe renal impairment', 'precaution', 'moderate', 'A levocetirizina é excretada por via renal; a dose deve ser ajustada.', 'Levocetirizine is renally excreted; the dose must be adjusted.', 'Ajustar a dose de acordo com a depuração de creatinina.', 'Adjust the dose according to creatinine clearance.', 'EMC-UK (MHRA) — SmPC aprovada Levocetirizina: https://www.medicines.org.uk/emc/product/9917/smpc', 'EMC-UK (MHRA) — approved Levocetirizine SmPC: https://www.medicines.org.uk/emc/product/9917/smpc', 1),
  ('difenidramina', 'glaucoma', 'Glaucoma de ângulo fechado', 'Angle-closure glaucoma', 'contraindication', 'critical', 'A difenidramina tem efeitos anticolinérgicos que podem precipitar glaucoma de ângulo fechado.', 'Diphenhydramine has anticholinergic effects that may precipitate angle-closure glaucoma.', 'Contraindicado em glaucoma de ângulo fechado não tratado.', 'Contraindicated in untreated angle-closure glaucoma.', 'EMC-UK (MHRA) — SmPC aprovada Difenidramina: https://www.medicines.org.uk/emc/product/1476/smpc', 'EMC-UK (MHRA) — approved Diphenhydramine SmPC: https://www.medicines.org.uk/emc/product/1476/smpc', 1),
  ('difenidramina', 'hipertrofia_prostatica', 'Hipertrofia prostática benigna', 'Benign prostatic hyperplasia', 'precaution', 'moderate', 'Os efeitos anticolinérgicos podem agravar a retenção urinária.', 'Anticholinergic effects may worsen urinary retention.', 'Usar com precaução em homens com hipertrofia prostática sintomática.', 'Use with caution in men with symptomatic prostatic hyperplasia.', 'EMC-UK (MHRA) — SmPC aprovada Difenidramina: https://www.medicines.org.uk/emc/product/1476/smpc', 'EMC-UK (MHRA) — approved Diphenhydramine SmPC: https://www.medicines.org.uk/emc/product/1476/smpc', 1),
  ('difenidramina', 'asma', 'Asma/DPOC (secreções espessas)', 'Asthma/COPD (thick secretions)', 'precaution', 'moderate', 'Os efeitos anticolinérgicos podem espessar as secreções e dificultar a expetoração.', 'Anticholinergic effects may thicken secretions and impair expectoration.', 'Usar com precaução em doentes com asma/DPOC.', 'Use with caution in patients with asthma/COPD.', 'EMC-UK (MHRA) — SmPC aprovada Difenidramina: https://www.medicines.org.uk/emc/product/1476/smpc', 'EMC-UK (MHRA) — approved Diphenhydramine SmPC: https://www.medicines.org.uk/emc/product/1476/smpc', 1),
  ('dexametasona', 'infeccao_ativa', 'Infeção ativa (incl. varicela/zona)', 'Active infection (incl. varicella/shingles)', 'contraindication', 'critical', 'Os corticosteroides podem mascarar e agravar infeções, incluindo varicela grave.', 'Corticosteroids may mask and worsen infections, including severe varicella.', 'Evitar em infeções sistémicas ativas sem antibioterapia.', 'Avoid in active systemic infections without antibiotic cover.', 'EMC-UK (MHRA) — SmPC aprovada Dexametasona: https://www.medicines.org.uk/emc/product/13196/smpc', 'EMC-UK (MHRA) — approved Dexamethasone SmPC: https://www.medicines.org.uk/emc/product/13196/smpc', 1),
  ('dexametasona', 'diabetes_mellitus', 'Diabetes mellitus', 'Diabetes mellitus', 'precaution', 'moderate', 'Os corticosteroides elevam a glicemia.', 'Corticosteroids raise blood glucose.', 'Monitorizar glicemia e ajustar antidiabéticos durante a terapêutica.', 'Monitor blood glucose and adjust antidiabetics during therapy.', 'EMC-UK (MHRA) — SmPC aprovada Dexametasona: https://www.medicines.org.uk/emc/product/13196/smpc', 'EMC-UK (MHRA) — approved Dexamethasone SmPC: https://www.medicines.org.uk/emc/product/13196/smpc', 1),
  ('dexametasona', 'osteoporose', 'Osteoporose', 'Osteoporosis', 'precaution', 'moderate', 'O uso prolongado de corticosteroides acelera a perda óssea.', 'Long-term corticosteroids accelerate bone loss.', 'Usar a menor dose/duração; considerar cálcio + vitamina D.', 'Use the lowest dose/duration; consider calcium + vitamin D.', 'EMC-UK (MHRA) — SmPC aprovada Dexametasona: https://www.medicines.org.uk/emc/product/13196/smpc', 'EMC-UK (MHRA) — approved Dexamethasone SmPC: https://www.medicines.org.uk/emc/product/13196/smpc', 1),
  ('dexametasona', 'glaucoma', 'Glaucoma', 'Glaucoma', 'precaution', 'moderate', 'Os corticosteroides podem elevar a pressão intraocular.', 'Corticosteroids may raise intraocular pressure.', 'Monitorizar pressão intraocular em terapêuticas prolongadas.', 'Monitor intraocular pressure on long-term therapy.', 'EMC-UK (MHRA) — SmPC aprovada Dexametasona: https://www.medicines.org.uk/emc/product/13196/smpc', 'EMC-UK (MHRA) — approved Dexamethasone SmPC: https://www.medicines.org.uk/emc/product/13196/smpc', 1),
  ('dexametasona', 'hipertensao_arterial', 'Hipertensão arterial', 'Hypertension', 'precaution', 'moderate', 'Os corticosteroides podem reter sódio e líquidos e elevar a tensão arterial.', 'Corticosteroids may retain sodium and fluid and raise blood pressure.', 'Monitorizar tensão arterial e ajustar anti-hipertensores se necessário.', 'Monitor blood pressure and adjust antihypertensives if needed.', 'EMC-UK (MHRA) — SmPC aprovada Dexametasona: https://www.medicines.org.uk/emc/product/13196/smpc', 'EMC-UK (MHRA) — approved Dexamethasone SmPC: https://www.medicines.org.uk/emc/product/13196/smpc', 1),
  ('dexametasona', 'ulcera_peptica_ativa', 'Úlcera péptica ativa', 'Active peptic ulcer', 'precaution', 'moderate', 'Os corticosteroides podem agravar úlcera péptica e o risco de hemorragia.', 'Corticosteroids may worsen peptic ulcer and bleeding risk.', 'Usar com precaução; considerar gastroprotecção.', 'Use with caution; consider gastroprotection.', 'EMC-UK (MHRA) — SmPC aprovada Dexametasona: https://www.medicines.org.uk/emc/product/13196/smpc', 'EMC-UK (MHRA) — approved Dexamethasone SmPC: https://www.medicines.org.uk/emc/product/13196/smpc', 1),
  ('adrenalina', 'cardiopatia_isquemica', 'Cardiopatia isquémica', 'Ischaemic heart disease', 'precaution', 'moderate', 'A adrenalina aumenta o trabalho miocárdico e pode precipitar isquemia/arritmias.', 'Epinephrine increases myocardial work and may precipitate ischaemia/arrhythmias.', 'Usar com precaução em doentes com cardiopatia isquémica; monitorizar.', 'Use with caution in ischaemic heart disease; monitor.', 'EMC-UK (MHRA) — SmPC aprovada Adrenalina: https://www.medicines.org.uk/emc/product/3673/smpc', 'EMC-UK (MHRA) — approved Epinephrine SmPC: https://www.medicines.org.uk/emc/product/3673/smpc', 1),
  ('adrenalina', 'hipertiroidismo', 'Hipertiroidismo', 'Hyperthyroidism', 'precaution', 'moderate', 'O hipertiroidismo potencia os efeitos da adrenalina (taquicardia, arritmias).', 'Hyperthyroidism potentiates the effects of epinephrine (tachycardia, arrhythmias).', 'Usar com precaução e monitorizar sintomas cardiovasculares.', 'Use with caution and monitor cardiovascular symptoms.', 'EMC-UK (MHRA) — SmPC aprovada Adrenalina: https://www.medicines.org.uk/emc/product/3673/smpc', 'EMC-UK (MHRA) — approved Epinephrine SmPC: https://www.medicines.org.uk/emc/product/3673/smpc', 1),
  ('adrenalina', 'hipertensao_arterial_grave', 'Hipertensão arterial grave', 'Severe hypertension', 'precaution', 'moderate', 'A adrenalina pode elevar marcadamente a tensão arterial.', 'Epinephrine may markedly raise blood pressure.', 'Usar com precaução e monitorizar tensão arterial.', 'Use with caution and monitor blood pressure.', 'EMC-UK (MHRA) — SmPC aprovada Adrenalina: https://www.medicines.org.uk/emc/product/3673/smpc', 'EMC-UK (MHRA) — approved Epinephrine SmPC: https://www.medicines.org.uk/emc/product/3673/smpc', 1),
  ('pseudoefedrina', 'hipertensao_arterial_grave', 'Hipertensão arterial grave', 'Severe hypertension', 'contraindication', 'critical', 'A pseudoefedrina (α-agonista) pode elevar a tensão arterial de forma acentuada.', 'Pseudoephedrine (α-agonist) may markedly raise blood pressure.', 'Contraindicado em hipertensão grave não controlada.', 'Contraindicated in severe uncontrolled hypertension.', 'EMC-UK (MHRA) — SmPC aprovada Pseudoefedrina: https://www.medicines.org.uk/emc/product/8292/smpc', 'EMC-UK (MHRA) — approved Pseudoephedrine SmPC: https://www.medicines.org.uk/emc/product/8292/smpc', 1),
  ('pseudoefedrina', 'cardiopatia_isquemica', 'Cardiopatia isquémica', 'Ischaemic heart disease', 'contraindication', 'critical', 'A pseudoefedrina pode precipitar angina e arritmias em doentes com cardiopatia isquémica.', 'Pseudoephedrine may precipitate angina and arrhythmias in ischaemic heart disease.', 'Contraindicado em doença coronária ativa.', 'Contraindicated in active coronary disease.', 'EMC-UK (MHRA) — SmPC aprovada Pseudoefedrina: https://www.medicines.org.uk/emc/product/8292/smpc', 'EMC-UK (MHRA) — approved Pseudoephedrine SmPC: https://www.medicines.org.uk/emc/product/8292/smpc', 1),
  ('pseudoefedrina', 'hipertiroidismo', 'Hipertiroidismo', 'Hyperthyroidism', 'precaution', 'moderate', 'O hipertiroidismo potencia os efeitos simpaticomiméticos.', 'Hyperthyroidism potentiates sympathomimetic effects.', 'Usar com precaução; evitar em hipertiroidismo não controlado.', 'Use with caution; avoid in uncontrolled hyperthyroidism.', 'EMC-UK (MHRA) — SmPC aprovada Pseudoefedrina: https://www.medicines.org.uk/emc/product/8292/smpc', 'EMC-UK (MHRA) — approved Pseudoephedrine SmPC: https://www.medicines.org.uk/emc/product/8292/smpc', 1),
  ('pseudoefedrina', 'glaucoma', 'Glaucoma de ângulo fechado', 'Angle-closure glaucoma', 'contraindication', 'critical', 'A pseudoefedrina pode precipitar crise de glaucoma de ângulo fechado.', 'Pseudoephedrine may precipitate angle-closure glaucoma crisis.', 'Contraindicado em glaucoma de ângulo fechado.', 'Contraindicated in angle-closure glaucoma.', 'EMC-UK (MHRA) — SmPC aprovada Pseudoefedrina: https://www.medicines.org.uk/emc/product/8292/smpc', 'EMC-UK (MHRA) — approved Pseudoephedrine SmPC: https://www.medicines.org.uk/emc/product/8292/smpc', 1),
  ('montelukast', 'doenca_hepatica_ativa', 'Doença hepática ativa', 'Active liver disease', 'precaution', 'moderate', 'O montelucaste é metabolizado no fígado; usar com precaução em doença hepática.', 'Montelukast is hepatically metabolised; use with caution in liver disease.', 'Monitorizar função hepática em doentes com doença hepática.', 'Monitor liver function in patients with liver disease.', 'EMC-UK (MHRA) — SmPC aprovada Montelucaste: https://www.medicines.org.uk/emc/product/1222/smpc', 'EMC-UK (MHRA) — approved Montelukast SmPC: https://www.medicines.org.uk/emc/product/1222/smpc', 1)
