-- ----------------------------------------------------------------
-- 5. Gestação / Lactação (drug_pregnancy_info, 1:1 por fármaco)
-- ----------------------------------------------------------------
INSERT INTO public.drug_pregnancy_info
  (drug_id, pregnancy_category, risk_pt, risk_en, trimester_pt, trimester_en,
   lactation_pt, lactation_en, contraception_pt, contraception_en,
   source_pt, source_en, status)
SELECT d.id, v.pregnancy_category, v.risk_pt, v.risk_en, v.trimester_pt, v.trimester_en,
       v.lactation_pt, v.lactation_en, v.contraception_pt, v.contraception_en,
       v.source_pt, v.source_en, 'published'
FROM public.drugs d
JOIN (VALUES
  ('cetirizina', 'compatible', 'A cetirizina é um dos anti-histamínicos de eleição na gravidez; não demonstrou teratogenicidade nos estudos disponíveis.', 'Cetirizine is one of the preferred antihistamines in pregnancy; available studies show no teratogenicity.', 'Pode ser usada em todos os trimestres quando indicado, na menor dose eficaz.', 'Can be used in all trimesters when indicated, at the lowest effective dose.', 'Excretada no leite materno em pequenas quantidades; compatível com o aleitamento.', 'Excreted into breast milk in small amounts; compatible with breastfeeding.', 'Sem contraceção adicional específica.', 'No specific additional contraception.', 'EMC-UK (MHRA) — SmPC aprovada Cetirizina: https://www.medicines.org.uk/emc/product/3217/smpc', 'EMC-UK (MHRA) — approved Cetirizine SmPC: https://www.medicines.org.uk/emc/product/3217/smpc'),
  ('loratadina', 'compatible', 'A loratadina é considerada compatível na gravidez (grande experiência de uso).', 'Loratadine is considered compatible in pregnancy (extensive use experience).', 'Pode ser usada quando indicado, na menor dose eficaz.', 'Can be used when indicated, at the lowest effective dose.', 'Excretada no leite em pequenas quantidades; compatível.', 'Excreted into milk in small amounts; compatible.', 'Sem contraceção adicional específica.', 'No specific additional contraception.', 'EMC-UK (MHRA) — SmPC aprovada Loratadina: https://www.medicines.org.uk/emc/product/10942/smpc', 'EMC-UK (MHRA) — approved Loratadine SmPC: https://www.medicines.org.uk/emc/product/10942/smpc'),
  ('desloratadina', 'caution', 'Dados limitados na gravidez; metabolito ativo da loratadina.', 'Limited data in pregnancy; active loratadine metabolite.', 'Usar apenas se o benefício justificar o risco; preferir loratadina/cetirizina se disponíveis.', 'Use only if benefit justifies risk; prefer loratadine/cetirizine when available.', 'Dados limitados; preferir evitar durante a amamentação.', 'Limited data; prefer to avoid during breastfeeding.', 'Sem contraceção adicional específica.', 'No specific additional contraception.', 'EMC-UK (MHRA) — SmPC aprovada Desloratadina: https://www.medicines.org.uk/emc/product/14722/smpc', 'EMC-UK (MHRA) — approved Desloratadine SmPC: https://www.medicines.org.uk/emc/product/14722/smpc'),
  ('fexofenadina', 'compatible', 'A fexofenadina (metabolito da terfenadina) não demonstrou teratogenicidade nos estudos disponíveis.', 'Fexofenadine (terfenadine metabolite) showed no teratogenicity in available studies.', 'Pode ser usada quando indicado, na menor dose eficaz.', 'Can be used when indicated, at the lowest effective dose.', 'Dados limitados na amamentação; considerar alternativa com mais dados.', 'Limited breastfeeding data; consider an alternative with more data.', 'Sem contraceção adicional específica.', 'No specific additional contraception.', 'EMC-UK (MHRA) — SmPC aprovada Fexofenadina: https://www.medicines.org.uk/emc/product/13208/smpc', 'EMC-UK (MHRA) — approved Fexofenadine SmPC: https://www.medicines.org.uk/emc/product/13208/smpc'),
  ('levocetirizina', 'caution', 'Dados limitados na gravidez; enantiómero ativo da cetirizina.', 'Limited data in pregnancy; active cetirizine enantiomer.', 'Usar apenas se o benefício justificar o risco; preferir cetirizina se disponível.', 'Use only if benefit justifies risk; prefer cetirizine when available.', 'Dados limitados; preferir evitar durante a amamentação.', 'Limited data; prefer to avoid during breastfeeding.', 'Sem contraceção adicional específica.', 'No specific additional contraception.', 'EMC-UK (MHRA) — SmPC aprovada Levocetirizina: https://www.medicines.org.uk/emc/product/9917/smpc', 'EMC-UK (MHRA) — approved Levocetirizine SmPC: https://www.medicines.org.uk/emc/product/9917/smpc'),
  ('difenidramina', 'caution', 'Uso ocasional geralmente considerado seguro; evitar doses elevadas próximo do termo (risco teórico de efeitos oxitócicos/neonatais).', 'Occasional use is generally considered safe; avoid high doses near term (theoretical risk of oxytocic/neonatal effects).', 'Usar a menor dose possível e por curta duração.', 'Use the lowest possible dose for a short duration.', 'Concentrações no leite baixas; uso ocasional compatível com vigilância do lactente.', 'Low milk levels; occasional use compatible with infant monitoring.', 'Sem contraceção adicional específica.', 'No specific additional contraception.', 'EMC-UK (MHRA) — SmPC aprovada Difenidramina: https://www.medicines.org.uk/emc/product/1476/smpc', 'EMC-UK (MHRA) — approved Diphenhydramine SmPC: https://www.medicines.org.uk/emc/product/1476/smpc'),
  ('dexametasona', 'caution', 'Os corticosteroides atravessam a placenta; uso na gravidez apenas quando claramente indicado (ex.: maturação pulmonar fetal sob orientação).', 'Corticosteroids cross the placenta; use in pregnancy only when clearly indicated (e.g. fetal lung maturation under guidance).', 'Usar a menor dose eficaz e a mais curta duração.', 'Use the lowest effective dose for the shortest duration.', 'Baixas doses compatíveis com amamentação; doses elevadas: aguardar 3-4 h após a toma.', 'Low doses are compatible with breastfeeding; high doses: wait 3-4 h after dosing.', 'Sem contraceção adicional específica.', 'No specific additional contraception.', 'EMC-UK (MHRA) — SmPC aprovada Dexametasona: https://www.medicines.org.uk/emc/product/13196/smpc', 'EMC-UK (MHRA) — approved Dexamethasone SmPC: https://www.medicines.org.uk/emc/product/13196/smpc'),
  ('adrenalina', 'caution', 'A adrenalina é usada em emergências (anafilaxia) na gravidez quando o benefício supera o risco; o risco de hipoperfusão materna/fetal não tratada é maior que o da exposição.', 'Epinephrine is used in emergencies (anaphylaxis) in pregnancy when benefit outweighs risk; the risk of untreated maternal/fetal hypoperfusion exceeds exposure risk.', 'Usar apenas em emergência sob orientação médica.', 'Use only in emergencies under medical guidance.', 'Não contraindica a amamentação após uso agudo.', 'Does not contraindicate breastfeeding after acute use.', 'Sem contraceção adicional específica.', 'No specific additional contraception.', 'EMC-UK (MHRA) — SmPC aprovada Adrenalina: https://www.medicines.org.uk/emc/product/3673/smpc', 'EMC-UK (MHRA) — approved Epinephrine SmPC: https://www.medicines.org.uk/emc/product/3673/smpc'),
  ('pseudoefedrina', 'caution', 'Evitar no 1.º trimestre (dados limitados); usar a menor dose pelo menor tempo.', 'Avoid in the 1st trimester (limited data); use the lowest dose for the shortest time.', 'Usar apenas se claramente necessário e com precaução.', 'Use only if clearly necessary and with caution.', 'Dados limitados; preferir evitar durante a amamentação.', 'Limited data; prefer to avoid during breastfeeding.', 'Sem contraceção adicional específica.', 'No specific additional contraception.', 'EMC-UK (MHRA) — SmPC aprovada Pseudoefedrina: https://www.medicines.org.uk/emc/product/8292/smpc', 'EMC-UK (MHRA) — approved Pseudoephedrine SmPC: https://www.medicines.org.uk/emc/product/8292/smpc')
) AS v(slug, pregnancy_category, risk_pt, risk_en, trimester_pt, trimester_en,
       lactation_pt, lactation_en, contraception_pt, contraception_en,
       source_pt, source_en)
ON d.slug = v.slug
ON CONFLICT (drug_id) DO NOTHING;